DO $$
BEGIN
  IF to_regclass('public.read_audit') IS NOT NULL THEN
    EXECUTE 'TRUNCATE read_audit';
  END IF;
END
$$;
TRUNCATE list_cursors, create_rejection_audit, mutation_audit, idempotency_records, revision_subjects, lexical_representations,
  subjects, collection_grants, revisions, items, collections, credentials, apps,
  principals, tenant_authority, tenants CASCADE;

UPDATE items SET active_revision_id = CASE id
  WHEN '40000000000000000000000000000001' THEN '50000000000000000000000000000001'
  WHEN '40000000000000000000000000000002' THEN '50000000000000000000000000000002'
  WHEN '40000000000000000000000000000003' THEN '50000000000000000000000000000003'
END;
